let b = $json;
if (b && typeof b.body === 'object' && b.body !== null && !Array.isArray(b.body)) {
  b = b.body;
} else if (b && typeof b.body === 'string' && b.body.trim().startsWith('{')) {
  try { b = JSON.parse(b.body); } catch (e) {}
}

const TZ = 'Europe/Berlin';
const MAX_DAYS_AHEAD = 90;
const ALLOWED_TIMES = new Set([
  '09:00','09:30','10:00','10:30','11:00','11:30',
  '13:00','13:30','14:00','14:30','15:00','15:30',
  '16:00','16:30'
]);

const clean = (v, max = 5000) => (v ?? '').toString().trim().slice(0, max);
const name = clean(b.name, 120);
const email = clean(b.email, 254).toLowerCase();
const company = clean(b.company, 160);
const topic = clean(b.topic || 'Erstgespräch', 120);
const message = clean(b.message, 2000);
const day = clean(b.preferred_day, 10);
const time = clean(b.preferred_time, 5);

const out = {
  name, email, company, topic, message, day, time,
  timezone: TZ,
  valid: false,
  hasSlot: false
};

if (!name || !email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  out.error = 'Name und eine gültige E-Mail-Adresse sind erforderlich.';
  return [{ json: out }];
}

if (!day && !time) {
  out.valid = true;
  return [{ json: out }];
}

if (!day || !time) {
  out.error = 'Bitte wählen Sie Wunschtag und Wunschzeit vollständig aus.';
  return [{ json: out }];
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !/^\d{2}:\d{2}$/.test(time)) {
  out.error = 'Ungültiges Datums- oder Zeitformat.';
  return [{ json: out }];
}

if (!ALLOWED_TIMES.has(time)) {
  out.error = 'Diese Uhrzeit ist nicht buchbar. Bitte wählen Sie einen angebotenen 30-Minuten-Slot.';
  return [{ json: out }];
}

const [yy, mm, dd] = day.split('-').map(Number);
const [hh, mi] = time.split(':').map(Number);

function partsAt(utcMs, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hourCycle: 'h23'
  });
  const obj = {};
  for (const p of fmt.formatToParts(new Date(utcMs))) {
    if (p.type !== 'literal') obj[p.type] = p.value;
  }
  return obj;
}

function offsetMsAt(utcMs, timeZone) {
  const p = partsAt(utcMs, timeZone);
  const localAsUtc = Date.UTC(
    Number(p.year), Number(p.month) - 1, Number(p.day),
    Number(p.hour), Number(p.minute), Number(p.second)
  );
  return localAsUtc - utcMs;
}

function localBerlinToUtc(y, m, d, h, min) {
  const wallClockAsUtc = Date.UTC(y, m - 1, d, h, min, 0);
  let offset = offsetMsAt(wallClockAsUtc, TZ);
  let utcMs = wallClockAsUtc - offset;
  const correctedOffset = offsetMsAt(utcMs, TZ);
  if (correctedOffset !== offset) utcMs = wallClockAsUtc - correctedOffset;
  return new Date(utcMs);
}

const start = localBerlinToUtc(yy, mm, dd, hh, mi);
if (Number.isNaN(start.getTime())) {
  out.error = 'Der gewünschte Termin konnte nicht verarbeitet werden.';
  return [{ json: out }];
}

const roundTrip = partsAt(start.getTime(), TZ);
const sameLocalTime =
  Number(roundTrip.year) === yy &&
  Number(roundTrip.month) === mm &&
  Number(roundTrip.day) === dd &&
  Number(roundTrip.hour) === hh &&
  Number(roundTrip.minute) === mi;

if (!sameLocalTime) {
  out.error = 'Der gewünschte Termin ist in der Zeitzone Europe/Berlin nicht gültig.';
  return [{ json: out }];
}

const weekday = new Intl.DateTimeFormat('en-US', { timeZone: TZ, weekday: 'short' }).format(start);
if (weekday === 'Sat' || weekday === 'Sun') {
  out.error = 'Termine sind aktuell nur Montag bis Freitag buchbar.';
  return [{ json: out }];
}

const now = new Date();
if (start.getTime() <= now.getTime() + 5 * 60 * 1000) {
  out.error = 'Bitte wählen Sie einen Termin in der Zukunft.';
  return [{ json: out }];
}

if (start.getTime() > now.getTime() + MAX_DAYS_AHEAD * 24 * 60 * 60 * 1000) {
  out.error = `Termine können maximal ${MAX_DAYS_AHEAD} Tage im Voraus gebucht werden.`;
  return [{ json: out }];
}

const end = new Date(start.getTime() + 30 * 60 * 1000);

out.valid = true;
out.hasSlot = true;
out.startIso = start.toISOString();
out.endIso = end.toISOString();
out.displayDate = `${String(dd).padStart(2,'0')}.${String(mm).padStart(2,'0')}.${yy}`;
out.displayTime = `${String(hh).padStart(2,'0')}:${String(mi).padStart(2,'0')}`;
out.requestedLocal = `${day}T${time}:00`;
return [{ json: out }];

const req = $('Validieren & Slot').first().json;
const r = $json || {};
return [{ json: { ...req, booked: r.booked === true, booking_id: r.booking_id || '' } }];

const req = $('Validieren & Slot').first().json;
const ctx = $json || {};
return [{ json: { ...req, booking_id: ctx.booking_id || '', booked: ctx.booked === true } }];

const ctx = $json || {};
function fmtIcs(iso) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, ''); // 20261001T090000Z
}
const uid = (ctx.booking_id || ('bk-' + ctx.email + '-' + ctx.startIso)).replace(/[^a-zA-Z0-9@._-]/g, '-');
const summary = 'Skalantech Erstgespräch · ' + (ctx.name || '') + (ctx.company ? ' · ' + ctx.company : '');
const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Skalantech//Terminbuchung//DE',
  'CALSCALE:GREGORIAN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  'UID:' + uid + '@skalantech.store',
  'DTSTAMP:' + fmtIcs(new Date().toISOString()),
  'DTSTART:' + fmtIcs(ctx.startIso),
  'DTEND:' + fmtIcs(ctx.endIso),
  'SUMMARY:' + summary,
  'DESCRIPTION:' + (ctx.topic || 'Erstgespräch').replace(/[\r\n]+/g, ' '),
  'LOCATION:Online (Details folgen)',
  'ORGANIZER;CN=Xavier Escalante:mailto:xyesca@skalantech.store',
  'ATTENDEE;CN=' + (ctx.name || '') + ';ROLE=REQ-PARTICIPANT;RSVP=TRUE:mailto:' + (ctx.email || ''),
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n');
return [{ json: ctx, binary: { data: { data: Buffer.from(ics, 'utf8').toString('base64'), mimeType: 'text/calendar', fileName: 'skalantech-erstgespraech.ics' } } }];

// Deterministische Bestätigungsmail (kein LLM im Terminpfad — Issue #15)
const ctx = $('Event-Kontext zusammenführen').first().json;

function esc(v = '') {
  return String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const name = String(ctx.name || '').trim();
const company = String(ctx.company || '').trim();
const topic = String(ctx.topic || 'Erstgespräch').trim();
const message = String(ctx.message || '').trim();
const when = `${ctx.displayDate} um ${ctx.displayTime} Uhr`;

// Persönlicher Absatz deterministisch aus Template-Bausteinen
let personal;
if (message && topic && topic !== 'Erstgespräch') {
  personal = `Vielen Dank für Ihre Nachricht zum Thema ${esc(topic)}. Ich schaue mir Ihre Ausgangslage vor unserem Gespräch an.`;
} else if (message && company) {
  personal = `Vielen Dank für Ihre Nachricht zu ${esc(company)}. Ich schaue mir Ihre Ausgangslage vor unserem Gespräch an.`;
} else if (message) {
  personal = 'Vielen Dank für Ihre Nachricht. Ich schaue mir Ihre Ausgangslage vor unserem Gespräch an.';
} else if (topic && topic !== 'Erstgespräch') {
  personal = `Ich freue mich auf unser Gespräch zum Thema ${esc(topic)}.`;
} else if (company) {
  personal = `Ich freue mich auf unser Gespräch zu ${esc(company)}.`;
} else {
  personal = 'Ich freue mich auf unser Gespräch.';
}

const aiEmail = [
  `<p>Hallo ${esc(name)},</p>`,
  `<p>Ihr Erstgespräch mit Skalantech ist für <strong>${esc(when)}</strong> eingetragen. Geplant sind 30 Minuten.</p>`,
  `<p>${personal}</p>`,
  '<p>Die Kalendereinladung (ICS) liegt dieser E-Mail bei.</p>',
  '<p>Bis dann.<br>Xavier Escalante<br>Skalantech</p>'
].join('');

return [{ json: { ...ctx, aiEmail, aiPersonal: personal } }];
